// ❌ REACT: Every click re-executes this entire function,
// recalculating variables and re-allocating inline event handler functions.
import { useState } from 'react';

export default function Counter() {
  const [count, setCount] = useState(0);

  console.log('Component function executed!'); // Logs on every single count increment

  return <button onClick={() => setCount(c => c + 1)}>Count: {count}</button>;
}

// ✅ SOLIDJS: Component function executes ONLY ONCE at mount.
// The button click triggers only the exact {count()} text node update.
import { createSignal } from 'solid-js';

export default function Counter() {
  const [count, setCount] = createSignal(0);

  console.log('Component initialized!'); // Logs EXACTLY ONCE, never logs again!

  return <button onClick={() => setCount(c => c + 1)}>Count: {count()}</button>;
}
